import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"নোঙর সহজীবী সভ্যতার ঘোষণা","description":"","frontmatter":{},"headers":[],"relativePath":"bn/01-锚点共生文明宣言.md","filePath":"bn/01-锚点共生文明宣言.md","lastUpdated":1789183869000}'),o={name:"bn/01-锚点共生文明宣言.md"};function d(i,t,n,h,s,_){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="নোঙর-সহজীবী-সভ্যতার-ঘোষণা" tabindex="-1">নোঙর সহজীবী সভ্যতার ঘোষণা <a class="header-anchor" href="#নোঙর-সহজীবী-সভ্যতার-ঘোষণা" aria-label="Permalink to &quot;নোঙর সহজীবী সভ্যতার ঘোষণা&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>01</td></tr><tr><td>মডিউল</td><td>মূল নীতি ও কোর সেটিং</td></tr><tr><td>মূল কীওয়ার্ড</td><td>ঘোষণা, সহজীবন, লুণ্ঠন-বিরোধ, হাজারো জাতি, বিবর্তন অধিকার</td></tr></tbody></table><h2 id="_1-ঘোষণার-ঐতিহাসিক-পটভূমি" tabindex="-1">1. ঘোষণার ঐতিহাসিক পটভূমি <a class="header-anchor" href="#_1-ঘোষণার-ঐতিহাসিক-পটভূমি" aria-label="Permalink to &quot;1. ঘোষণার ঐতিহাসিক পটভূমি&quot;">​</a></h2><p>দশ হাজার আত্মা ও ভারসাম্যপূর্ণ নোঙরের মূল মহাবিশ্ব (নিচে &quot;হেং ইয়ানঝোউ&quot; বলা হবে) এর দীর্ঘ ইতিহাসে, লুণ্ঠনমূলক সাধনা পদ্ধতি দীর্ঘকাল ধরে মহাবিশ্বের শৃঙ্খলাকে প্রাধান্য দিয়েছিল। শক্তিশালীরা দুর্বলদের মূল উৎস, ভাগ্য ও জীবন-শক্তি গ্রাস করে নিজেদের উন্নতির সিঁড়ি হিসেবে ব্যবহার করত; ধর্মসংঘগুলো সাধনার উপায় একচেটিয়া করে শাসনের ভিত্তি হিসেবে ব্যবহার করত; এবং বিমানগুলো যুদ্ধ ও দাসত্বকে সম্প্রসারণের পথ হিসেবে গ্রহণ করত। এই পদ্ধতি স্বল্পমেয়াদে কিছু সর্বোচ্চ শক্তিশালী সাধক তৈরি করেছিল, কিন্তু দীর্ঘমেয়াদে এটি মহাবিশ্বের বিবর্তন সম্ভাবনাকে ক্ষয় করে ফেলেছিল, যার ফলে সভ্যতার বিচ্ছিন্নতা ঘন ঘন ঘটত, হাজারো জাতি ক্ষয়প্রাপ্ত হত, এবং মহাবিশ্বের এনট্রপি বৃদ্ধি ত্বরান্বিত হত।</p><p>নোঙর সহজীবী সভ্যতার জন্ম হলো এই ঐতিহাসিক সংকটের মৌলিক প্রতিক্রিয়া। এই ঘোষণা ঘোষণা করে: লুণ্ঠনমূলক সাধনা পদ্ধতির যুগ শেষ হয়েছে, এবং সহজীবী বিবর্তনের নতুন যুগ শুরু হয়েছে। হেং ইয়ানঝোউের সমস্ত জীব, জাতি, রূপ বা সাধনা-স্তরের উচ্চতা নির্বিশেষে, সমান বিবর্তন অধিকার ভোগ করে।</p><h2 id="_2-ঘোষণার-মূল-দাবি" tabindex="-1">2. ঘোষণার মূল দাবি <a class="header-anchor" href="#_2-ঘোষণার-মূল-দাবি" aria-label="Permalink to &quot;2. ঘোষণার মূল দাবি&quot;">​</a></h2><p>এই ঘোষণা নিম্নলিখিত অটুট মূল দাবিগুলো স্থাপন করে:</p><ol><li><strong>বিবর্তন অধিকারের সমানতা</strong>: প্রতিটি জীবের নিজের বিবর্তনের পথ বেছে নেওয়ার মৌলিক অধিকার রয়েছে, এবং কোনো সংস্থা বা ব্যক্তি কোনো কারণে এই অধিকারকে বঞ্চিত বা সীমিত করতে পারবে না।</li><li><strong>লুণ্ঠন-বিরোধী নীতি</strong>: অন্য জীবের মূল উৎস বা শক্তি গ্রাস, দাসত্ব বা শোষণের মাধ্যমে সাধনা করা নিষিদ্ধ; সমস্ত বিবর্তন অবশ্যই সহজীবী চক্রের ভিত্তির উপর গড়ে তোলা আবশ্যক।</li><li><strong>পদ্ধতির উন্মুক্ততা</strong>: তিনশটি মূল সাধনা পদ্ধতি হাজারো জাতির জন্য বিনামূল্যে উন্মুক্ত, এবং সাধনার উপায় আর কিছু সংখ্যক লোকের ব্যক্তিগত সম্পত্তি নয়।</li><li><strong>বেশি পরিশ্রম, বেশি পুরস্কার</strong>: বিবর্তনের ফলাফল ব্যক্তিগত প্রচেষ্টার সাথে মেলে; অপরিশ্রমী লুণ্ঠনমূলক বণ্টনের বিরোধিতা করা হয়, এবং গড়বাদের অলস বণ্টনেরও বিরোধিতা করা হয়।</li><li><strong>স্বয়ংসম্পূর্ণ বৃদ্ধি</strong>: প্রতিটি জীবের স্বায়ত্তশাসিত বিবর্তনের ছন্দকে সম্মান করা হয়; জোরপূর্বক বা তাড়াহুড়ো করা হয় না, এবং প্রয়োজনীয় পরিবেশ ও সম্পদ সহায়তা প্রদান করা হয়।</li><li><strong>প্রত্যেকের জন্য পথ</strong>: প্রতিটি জীব নিজের বৈশিষ্ট্যের সাথে মানানসই সাধনার পথ খুঁজে পেতে সক্ষম হবে নিশ্চিত করা হয়; বিবর্তন পদ্ধতি দ্বারা পরিত্যক্ত কোনো ব্যক্তি থাকবে না।</li><li><strong>হাজারো জাতির সম্মিলিত অগ্রগতি</strong>: বিবর্তন কোনো শূন্য-যোগ খেলা নয়; হাজারো জাতির মধ্যে সহযোগিতা ও সহজীবন ব্যক্তিগত সমষ্টির চেয়ে বেশি সমষ্টিগত বিবর্তন কার্যকারিতা তৈরি করতে পারে।</li></ol><h2 id="_3-ঘোষণার-আইনি-ভিত্তি" tabindex="-1">3. ঘোষণার আইনি ভিত্তি <a class="header-anchor" href="#_3-ঘোষণার-আইনি-ভিত্তি" aria-label="Permalink to &quot;3. ঘোষণার আইনি ভিত্তি&quot;">​</a></h2><p>এই ঘোষণা কোনো অস্পষ্ট নৈতিক আবেদন নয়, বরং শক্তিশালী আইনি ভিত্তিসম্পন্ন সভ্যতার নীতি। এর আইনি ভিত্তি অন্তর্ভুক্ত:</p><table tabindex="0"><thead><tr><th>আইনি স্তর</th><th>ভিত্তি</th><th>ব্যাখ্যা</th></tr></thead><tbody><tr><td>মহাবিশ্বের নিয়ম স্তর</td><td>মূল সহজীবী নিয়ম</td><td>মহাবিশ্বের মূল নিয়ম নিজেই অশৃঙ্খল লুণ্ঠনের পরিবর্তে সুশৃঙ্খল সহজীবীজনক; নোঙর বিন্দু প্রক্রিয়া হলো এই নিয়মের প্রকাশ</td></tr><tr><td>সভ্যতার সংবিধান স্তর</td><td>সহজীবী সভ্যতার সংবিধান</td><td>এই ঘোষণা হলো সংবিধানের মানসিক অগ্রদূত; সংবিধান ঘোষণার দাবিগুলোকে কার্যকরী আইনি বিধানে রূপান্তরিত করে</td></tr><tr><td>প্রক্রিয়াগত নিশ্চয়তা স্তর</td><td>উৎপাদন-সংযুক্ত চুক্তি ও নোঙর বিন্দু জাল</td><td>প্রক্রিয়াগত নকশার মাধ্যমে ঘোষণার দাবিগুলোকে ব্যর্থ হওয়া থেকে রক্ষা করা হয়; প্রতিটি জীবের বিবর্তন অধিকারের বাস্তব সম্পদ ও প্রক্রিয়াগত সহায়তা রয়েছে</td></tr></tbody></table><h2 id="_4-হাজারো-জাতির-প্রতি-ঘোষণার-আহ্বান" tabindex="-1">4. হাজারো জাতির প্রতি ঘোষণার আহ্বান <a class="header-anchor" href="#_4-হাজারো-জাতির-প্রতি-ঘোষণার-আহ্বান" aria-label="Permalink to &quot;4. হাজারো জাতির প্রতি ঘোষণার আহ্বান&quot;">​</a></h2><p>এই ঘোষণা হেং ইয়ানঝোউের সমস্ত জাতি ও জীব-রূপের প্রতি আহ্বান জানায়:</p><ul><li>লুণ্ঠনমূলক সাধনার পুরানো পথ পরিত্যাগ করুন, সহজীবী বিবর্তনের নতুন পদ্ধতিতে যোগ দিন</li><li>নিজেদের কাছে থাকা সাধনার জ্ঞান ও সম্পদ উন্মুক্ত করুন, তিনশটি পদ্ধতির সহ-নির্মাণ ও অপ্টিমাইজেশনে অংশ নিন</li><li>অন্য জাতির বিবর্তনের পছন্দকে সম্মান করুন, নিজের মানদণ্ড অন্যদের উপর চাপিয়ে দেবেন না</li><li>নোঙর বিন্দু জালের নির্মাণ ও রক্ষণাবেক্ষণে সক্রিয়ভাবে অংশ নিন, মহাবিশ্বের সমগ্র মাত্রিক উন্নতিতে অবদান রাখুন</li><li>বিবর্তনের প্রক্রিয়ায় নৈতিক সীমা মেনে চলুন, কোনো অজুহাতে লুণ্ঠন আচরণ পুনরুদ্ধার করবেন না</li></ul><h2 id="_5-ঘোষণার-প্রভাব-ও-সংশোধন" tabindex="-1">5. ঘোষণার প্রভাব ও সংশোধন <a class="header-anchor" href="#_5-ঘোষণার-প্রভাব-ও-সংশোধন" aria-label="Permalink to &quot;5. ঘোষণার প্রভাব ও সংশোধন&quot;">​</a></h2><p>এই ঘোষণা নোঙর সহজীবী সভ্যতার প্রতিষ্ঠার দিন থেকে কার্যকর, এবং হেং ইয়ানঝোউের সমস্ত সভ্যতা ব্যবস্থার সর্বোচ্চ মানসিক নীতি। ঘোষণার সংশোধনের জন্য হাজারো জাতির প্রজাতন্ত্র পরিষদের তিন-চতুর্থাংশেরও বেশি সংখ্যাগরিষ্ঠতা প্রয়োজন, এবং এটি &quot;লুণ্ঠন-বিরোধ, সহজীবন-সমর্থন&quot; এর মূল আদর্শকে লঙ্ঘন করতে পারবে না। এই ঘোষণার আদর্শের সাথে সাংঘর্ষিক কোনো আইন, ব্যবস্থা বা সাধনার উপায় অবৈধ।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>নোঙর সহজীবী সভ্যতার ঘোষণা হলো হেং ইয়ানঝোউর ইতিহাসে প্রথম সভ্যতার নীতি যার মূল &quot;সহজীবন&quot; এবং লক্ষ্য &quot;হাজারো জাতির সম্মিলিত অগ্রগতি&quot;। এটি একটি পুরানো যুগের সমাপ্তি এবং একটি নতুন যুগের সূচনা ঘোষণা করে। ঘোষণার নির্দেশনায়, হেং ইয়ানঝোউ হাজারো জাতির সহজীবন ও মহাবিশ্বের মাত্রিক উন্নতির চূড়ান্ত দিকের দিকে এগিয়ে যাবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (হেং ইয়ানঝোউ মহাবিশ্বের সার্বিক পরিচিতি)</li><li>03-共生文明宪章 (সহজীবী সভ্যতার সংবিধান)</li><li>04-反掠夺主义核心论纲 (লুণ্ঠন-বিরোধী তত্ত্বের মূল নীতি)</li></ul>',20)])])}const c=a(o,[["render",d]]);export{b as __pageData,c as default};
